ST.xhtml:p:
IF bInput THEN
  CASE nLightState OF
    0:
      IF bInput AND bSparkle THEN
        nLightState := 5;
      ELSIF bInput AND NOT bSparkle THEN
        nLightState := 20;
      END_IF;
      TonLightOn(IN := FALSE);
      TonLightOFF(IN := FALSE);
    5:
      bOutput := TRUE;
      TonLightOn(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nStartTime)));
      IF TonLightOn.Q THEN
        TonLightOn(IN := FALSE);
        nLightState := 10;
      END_IF; 
    10:
      bOutput := FALSE;
      TonLightOFF(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(nStopTime)));
      IF TonLightOFF.Q THEN
        TonLightOFF(IN := FALSE);
        nLightState := 5;
      END_IF;  
    20:
      bOutput := TRUE;  
  END_CASE;
ELSE
  bOutput := FALSE;
  nLightState := 0;
END_IF;
